-- The SQLite fixture (K29): run on a new file by the tests, never on a file
-- of the user's. Every common declared type, a WITHOUT ROWID table, a table
-- without a key, a composite key, foreign keys, views, a trigger and
-- indexes. The large table is generated by the test that needs it.

CREATE TABLE customers (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    name VARCHAR(80),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    vip BOOLEAN NOT NULL DEFAULT 0
);

CREATE TABLE products (
    sku TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    price NUMERIC(10, 2) NOT NULL CHECK (price >= 0),
    weight REAL,
    photo BLOB,
    attributes JSON,
    released DATE
) WITHOUT ROWID;

CREATE TABLE orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id INTEGER NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
    placed_on DATE NOT NULL,
    note TEXT
);

CREATE TABLE order_lines (
    order_id INTEGER NOT NULL REFERENCES orders,
    line_no INTEGER NOT NULL,
    sku TEXT NOT NULL REFERENCES products (sku),
    quantity INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY (order_id, line_no)
);

CREATE INDEX orders_customer ON orders (customer_id);
CREATE INDEX order_lines_sku ON order_lines (sku) WHERE quantity > 0;

-- No primary or unique key: read-only in the data view.
CREATE TABLE events (
    happened_at INTEGER,
    kind TEXT,
    payload
);

-- Every storage class, and the declared types that look like other ones.
CREATE TABLE all_types (
    id INTEGER PRIMARY KEY,
    i INTEGER,
    big BIGINT,
    r REAL,
    d DOUBLE PRECISION,
    n NUMERIC,
    dec DECIMAL(10, 4),
    t TEXT,
    v VARCHAR(20),
    c CHAR(3),
    b BLOB,
    bool BOOLEAN,
    day DATE,
    stamp DATETIME,
    at_time TIME,
    doc JSON,
    untyped
);

CREATE VIEW customer_orders AS
SELECT c.id AS customer_id, c.email, count(o.id) AS orders
FROM customers c LEFT JOIN orders o ON o.customer_id = c.id
GROUP BY c.id;

CREATE VIEW expensive_products AS
SELECT sku, title, price FROM products WHERE price > 100;

CREATE TRIGGER orders_note_default AFTER INSERT ON orders
WHEN NEW.note IS NULL
BEGIN
    UPDATE orders SET note = 'none' WHERE id = NEW.id;
    INSERT INTO events (happened_at, kind, payload) VALUES (unixepoch(), 'order', NEW.id);
END;

